// fleet's union of declared packs is around a dozen reads where the full canon catalog
// is three times that, and a warm load pays for none of them.

import * as gh from './github.mjs';
import { installedVersions } from '../../../../engine/installed-versions.mjs';
import { parseEngineVersion, parsePackVersion } from '../derive/fleet.mjs';

export async function readCanon(config, token) {
  if (!config?.canonRepo) return null;
  try {
    const repo = config.canonRepo;
    const meta = await gh.getRepo(repo, token);
    const ref = await gh.getHeadSha(repo, meta.default_branch, token);
    // Two-root form: the reference is normally the canon itself (repo root), but a
    // mount carries both files too, so a deployment pointed at a member still reads.
    const at = async (path) => (await gh.getTextAtSha(repo, ref, path, token))
      ?? (await gh.getTextAtSha(repo, ref, `.claudinite/shared/${path}`, token));

    const engineVersion = parseEngineVersion(await at('engine/version.mjs'));
    const packVersions = {};
    const pending = new Map();
    const packVersion = (id) => {
      // A local pack lives in the member's own tree — the canon has no version for it.
      if (!id || id.startsWith('local/')) return Promise.resolve(null);
      if (!pending.has(id)) {
        pending.set(id, (async () => {
          const v = parsePackVersion(await at(`packs/${id}/pack.mjs`).catch(() => null));
          if (v != null) packVersions[id] = v;
          return v;
        })());
      }
      return pending.get(id);
    };
    return { repo, ref, engineVersion, packVersions, packVersion };
  } catch {
    return null;
  // The member's flat descriptor file where its converge writes one: every pack's
  // descriptor in a single read, and the packs it names are exactly the ones that
  // contribute.
  let flat = null;
  try { flat = await readFlat({ repo, sha, token, paths, gh }, FLAT_DASHBOARD_PATH, 'dashboards'); } catch { flat = null; }

  const found = declaredPackIds(declaration)
    .map((pack) => ({ pack, path: flat ? (flat[pack] ? FLAT_DASHBOARD_PATH : null) : descriptorPathIn(paths, pack) }))
    .filter((f) => f.path);

  return (await Promise.all(found.map(async ({ pack, path }) => {
    let text;
    if (flat) text = entryText(flat[pack]);
    else {
      // A member whose converge predates the flat directory: one read per descriptor.
      // @legacy-tolerance advisory:legacy-shape-in-use retire:#2323
      try { text = await gh.getTextAtSha(repo, sha, path, token); } catch { return { pack, withheld: true }; }
    }
    // The listing said it was there, so a null here means the tree and the contents
    // API disagree — which is a fault about this pack, not about the page.
    if (text === null) return { pack, fault: 'its dashboard.json is in the tree but could not be fetched' };
// A file's text AT A SHA, therefore immutable and cached forever. This is where the
// bulk of a repeat load's savings come from: a roster of task declarations is one
// call each on a cold cache and zero on a warm one.
//
// 404 is an ANSWER, not a failure — an unadopted repo has no declaration file — and
// it is cached as such, so a fleet sweep does not re-ask every member every time.
export async function getTextAtSha(repo, sha, path, token) {
  const hit = immutable.get(repo, sha, path);
  if (hit !== undefined) { rate.served += 1; return hit; }

  if (frozen() || !budgetLeft()) throw new RateBudgetError(path);
  const res = await raw(`/repos/${repo}/contents/${encodeURI(path)}?ref=${encodeURIComponent(sha)}`,
    { token, accept: 'application/vnd.github.raw' });
  rate.spent += 1;
  if (res.status === 404) { immutable.set(repo, sha, path, null); return null; }
  if (!res.ok) throw await fail(res, path);
  const text = await res.text();
  immutable.set(repo, sha, path, text);
  return text;
}

// The tree at a sha — immutable for the same reason, and the single most expensive
// response the page fetches on a large repo.

