// The provenance files of a pack: id → { file, text, entries, errors, status, empty }.
export function provenanceFiles(packDir, io) {
  const dir = `${packDir}/${PROVENANCE_DIR}`;
  const out = new Map();
  for (const name of listFiles(io, dir)) {
