      }
      // A provenance file is meant to grow - advised, never refused.
      for (const [id, h] of filesNow) {
        if (!touched(h.file)) continue;
        const b = filesBefore.get(id);
        if (!b || b.text.trim() === '') continue;
        if (!h.text.startsWith(b.text.replace(/\s+$/, ''))) {
